text:
Here's a simple tracker with a goal of 8 glasses. Tap a glass to fill it, or use + and − below. It starts fresh each day and remembers your count on this device.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body{font-family:Segoe UI,sans-serif;max-width:360px;margin:20px auto;text-align:center;color:#1b2b3a}
  h1{font-size:20px;margin:0 0 4px}
  #date{color:#667;font-size:13px;margin-bottom:16px}
  #count{font-size:44px;font-weight:600;margin:8px 0}
  #msg{min-height:20px;font-size:14px;margin-bottom:12px}
  #glasses{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:12px 0 18px}
  .g{height:64px;border:2px solid #4a90d9;border-radius:4px 4px 14px 14px;background:#fff;cursor:pointer}
  .g.full{background:linear-gradient(#8ec5fc,#4a90d9)}
  .bar{height:8px;background:#e3ecf5;border-radius:4px;overflow:hidden;margin:0 0 16px}
  #fill{height:100%;width:0;background:#4a90d9;transition:width .2s}
  button.c{font-size:18px;width:56px;height:44px;margin:0 6px;border:0;border-radius:8px;background:#4a90d9;color:#fff;cursor:pointer}
  button.r{margin-top:18px;border:0;background:none;color:#667;text-decoration:underline;cursor:pointer}
</style>
</head>
<body>
  <h1>Water today</h1>
  <div id="date"></div>
  <div id="count">0 / 8</div>
  <div class="bar"><div id="fill"></div></div>
  <div id="msg"></div>
  <div id="glasses"></div>
  <button class="c" id="minus">−</button>
  <button class="c" id="plus">+</button><br>
  <button class="r" id="reset">Reset today</button>
<script>
  var GOAL=8, d=new Date(), key="water-"+d.toISOString().slice(0,10), n=0;
  try{n=parseInt(localStorage.getItem(key)||"0",10)||0;}catch(e){}
  document.getElementById("date").textContent=d.toDateString();
  var box=document.getElementById("glasses");
  for(var i=0;i<GOAL;i++){
    (function(i){
      var g=document.createElement("div");
      g.className="g";
      g.onclick=function(){set(n===i+1?i:i+1);};
      box.appendChild(g);
    })(i);
  }
  function set(v){
    n=Math.max(0,v);
    try{localStorage.setItem(key,String(n));}catch(e){}
    draw();
  }
  function draw(){
    document.getElementById("count").textContent=n+" / "+GOAL;
    document.getElementById("fill").style.width=Math.min(100,n/GOAL*100)+"%";
    var gs=box.children;
    for(var i=0;i<gs.length;i++) gs[i].className="g"+(i<n?" full":"");
    document.getElementById("msg").textContent=
      n>=GOAL?"Goal reached. Well done!":(GOAL-n)+" more to go";
  }
  document.getElementById("plus").onclick=function(){set(n+1);};
  document.getElementById("minus").onclick=function(){set(n-1);};
  document.getElementById("reset").onclick=function(){set(0);};
  draw();
</script>
</body>
</html>
